        with open(file_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError) as e:
        raise ValueError(f"Error reading JSON file: {e}")

    # 3. Verify root type
    if INPUT_JSON.get("type") == "object":
        if not isinstance(data, dict):
            raise ValueError("JSON root must be an object (dict).")
    else:
        raise ValueError("Schema root type not supported.")

    properties = INPUT_JSON.get("properties", {})
    required_fields = INPUT_JSON.get("required", [])

    # 4. Check required fields presence
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required field: '{field}'")

    # 5. Validate types according to schema
