                        f"Field '{field}' must be of type "
                        f"{expected_type.__name__}, got {type(data[field]).__name__}"
                    )

    # 6. Validate email format
    if "email" in data:
        email_value = data["email"]
        if not isinstance(email_value, str):
            raise ValueError("Field 'email' must be a string.")
        if re.fullmatch(EMAIL_REGEX, email_value) is None:
            raise ValueError(f"Invalid email format: '{email_value}'")

    # 7. Retrieve requested attribute
    if attribute not in data:
        raise ValueError(f"Requested attribute '{attribute}' not found in JSON.")

    # Ensure attribute is defined in schema and type matches (if specified)
    if attribute in properties:
        expected_type = properties[attribute].get("type")
        if expected_type is not None and not isinstance(data[attribute], expected_type):
            raise ValueError(
                f"Attribute '{attribute}' must be of type "
                f"{expected_type.__name__}, got {type(data[attribute]).__name__}"
            )

    return data[attribute]
