import json
import re
import pandas as pd

def task_func(json_str):
    # Handle empty or whitespace-only input
    if not json_str or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    # Only handle top-level dicts
    if not isinstance(data, dict):
        return pd.DataFrame()

    def double_number(x):
        """Return x doubled as float if numeric, else None."""
        try:
            num = float(x)
            return num * 2.0
        except (ValueError, TypeError):
            return None

    normalized = {}

    for key, value in data.items():
        # Skip nested dictionaries per spec
        if isinstance(value, dict):
            normalized[key] = value
            continue

        # Numeric types
        if isinstance(value, (int, float)):
            normalized[key] = float(value) * 2.0

        # Lists of numerics / strings
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, (int, float)):
                    new_list.append(float(item) * 2.0)
                elif isinstance(item, str):
                    # Extract first number from string
                    match = re.search(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', item)
                    if match:
                        doubled = double_number(match.group(0))
                        new_list.append(doubled)
                    else:
                        new_list.append(item)
                else:
                    new_list.append(item)
            normalized[key] = new_list

        # Strings: extract numeric content and double it
        elif isinstance(value, str):
            match = re.search(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', value)
            if match:
                doubled = double_number(match.group(0))
                normalized[key] = doubled
            else:
                normalized[key] = value

        else:
            normalized[key] = value

    # Try to build a DataFrame; if it fails, return empty DataFrame
    try:
        df = pd.DataFrame(normalized)
    except ValueError:
        return pd.DataFrame()

    # Ensure numeric columns are floats where possible
    for col in df.columns:
        df[col] = pd.to_numeric(df[col], errors='ignore')

    return df
